from typing import Literal

from pydantic import BaseModel, Field

# Chat ids are generated by the browser (crypto.randomUUID) and used in DynamoDB keys.
CHAT_ID_PATTERN = r"^[A-Za-z0-9-]{1,64}$"
MESSAGE_ID_PATTERN = r"^\d{13}-\d$"
DOC_ID_PATTERN = r"^\d{13}$"
MAX_LARGE_UPLOAD_BYTES = 20 * 1024 * 1024  # big files go browser -> S3 -> SQS worker
MAX_UPLOAD_BYTES = 4 * 1024 * 1024  # 4 MB file, ~5.4 MB as base64: fits Lambda's 6 MB request limit


class ChatRequest(BaseModel):
    message: str = Field(min_length=1, max_length=4000)
    # The chat id; one chat = one conversation with its own history.
    session_id: str | None = Field(default=None, pattern=CHAT_ID_PATTERN)
    # Title for a brand-new chat (generated in the browser from the first question).
    title: str | None = Field(default=None, max_length=120)
    # Edit / regenerate: the id of the user message to replace (it and everything after it are removed).
    replace_from: str | None = Field(default=None, pattern=MESSAGE_ID_PATTERN)
    # Ask for 2-3 follow-up question suggestions after the answer.
    suggest: bool = False


class UploadRequest(BaseModel):
    session_id: str = Field(pattern=CHAT_ID_PATTERN)
    title: str | None = Field(default=None, max_length=120)
    filename: str = Field(min_length=1, max_length=160)
    content_type: Literal["application/pdf", "image/png", "image/jpeg"]
    size: int = Field(gt=0, le=MAX_LARGE_UPLOAD_BYTES)


class Source(BaseModel):
    title: str | None = None
    uri: str | None = None
    excerpt: str | None = None
    pages: list[int] = []      # PDF page numbers the passages came from (from Bedrock metadata)
    sections: list[str] = []   # headings found in the passages (e.g. "Documents required")


class ChatResponse(BaseModel):
    answer: str
    session_id: str | None = None
    sources: list[Source] = []
    tool_used: str | None = None
    requires_human_review: bool = False
    emi: dict | None = None         # EMI inputs/result for the interactive card
    message_id: str | None = None   # id of the saved assistant message (for feedback)
    created_at: int | None = None   # epoch ms
    user_message_id: str | None = None  # id of the saved question (for edit / regenerate)
    suggestions: list[str] = []


class RenameRequest(BaseModel):
    title: str = Field(min_length=1, max_length=120)


class FeedbackRequest(BaseModel):
    rating: Literal["up", "down"] | None = None  # None clears it
    comment: str | None = Field(default=None, max_length=1000)  # optional written feedback


class DocumentUpload(BaseModel):
    session_id: str = Field(pattern=CHAT_ID_PATTERN)
    title: str | None = Field(default=None, max_length=120)
    filename: str = Field(min_length=1, max_length=160)
    content_type: Literal["application/pdf", "image/png", "image/jpeg"]
    data_base64: str = Field(min_length=1, max_length=(MAX_UPLOAD_BYTES * 4) // 3 + 8)
